defmodule Atlas.MCP.Tools.ConnectClaudeProvider do
  @moduledoc false

  use Atlas.MCP.Tool,
    name: "connect_claude_provider",
    schema: %{
      "type" => "object",
      "properties" => %{
        "token" => %{
          "type" => "string",
          "description" => "Subscription token generated by claude setup-token, not an Anthropic API key."
        }
      },
      "required" => ["token"],
      "additionalProperties" => false
    },
    output_schema: %{
      "type" => "object",
      "properties" => %{
        "provider" => %{"type" => "string", "enum" => ["claude"]},
        "credential_configured" => %{"type" => "boolean"}
      },
      "required" => ["provider", "credential_configured"],
      "additionalProperties" => false
    }

  alias Atlas.LLMs.Connections
  alias Atlas.MCP.Tool

  @impl EMCP.Tool
  def description do
    "Create or replace the current user's personal Claude Code subscription token. " <>
      "Validates its format, not upstream access; never returns credentials. " <>
      "Only use with the user's explicit approval: the token passes through the MCP client and model. " <>
      "Prefer the private browser form at /settings/llm-providers when possible."
  end

  def execute(conn, %{"token" => token}) do
    with :ok <- Tool.authorize_authenticated(conn, "Personal AI providers") do
      case Connections.connect_claude(Tool.current_user(conn), token) do
        {:ok, metadata} -> {:ok, Map.take(metadata, [:provider, :credential_configured])}
        {:error, :invalid_claude_token} -> {:error, "Supply the subscription token generated by claude setup-token."}
        {:error, _reason} -> {:error, "Could not save the personal Claude connection."}
      end
    end
  end

  def execute(_conn, _args), do: {:error, "A Claude setup token is required."}
end
